-- ==============================================================================\n-- EDA AND CLEANING\n-- ==============================================================================\n-- Exploratory queries and transformation logic extracted from the complete SQL.\n\nUSE DATABASE MARKETING_CAMP_ANALYSIS;\nUSE SCHEMA RAW_DATA;\n\n-- CUSTOMERS EDA\nDESC TABLE CUSTOMERS;\nSELECT COUNT(*) FROM CUSTOMERS;\nSELECT * FROM CUSTOMERS WHERE CUSTOMER_ID IS NULL OR EMAIL IS NULL;\nSELECT CUSTOMER_ID, COUNT(*) FROM CUSTOMERS GROUP BY CUSTOMER_ID HAVING COUNT(*) > 1;\nSELECT MIN(AGE), MAX(AGE) FROM CUSTOMERS;\n\n-- CUSTOMER_JOURNEY EDA\nDESC TABLE CUSTOMER_JOURNEY;\nSELECT * FROM CUSTOMER_JOURNEY WHERE JOURNEYID IS NULL OR CUSTOMERID IS NULL OR PRODUCTID IS NULL;\n\n-- Duplicate business key used in the project:\n-- CUSTOMERID + PRODUCTID + VISITDATE + STAGE + ACTION\nWITH DuplicateRecords AS\n(SELECT JourneyID, CustomerID, ProductID, VisitDate, Stage, Action, Duration,\nROW_NUMBER() OVER(PARTITION BY CustomerID, ProductID, VisitDate, Stage, Action ORDER BY JourneyID) AS Row_Num\nFROM CUSTOMER_JOURNEY)\nSELECT * FROM DuplicateRecords WHERE Row_Num > 1 ORDER BY JourneyID;\n\nSELECT MIN(VISITDATE), MAX(VISITDATE) FROM CUSTOMER_JOURNEY;\nSELECT ACTION, COUNT(ACTION) FROM CUSTOMER_JOURNEY GROUP BY ACTION ORDER BY COUNT(ACTION);\nSELECT STAGE, COUNT(STAGE) FROM CUSTOMER_JOURNEY GROUP BY STAGE ORDER BY COUNT(STAGE);\nSELECT MIN(DURATION), MAX(DURATION) FROM CUSTOMER_JOURNEY;\n\n-- FINAL CLEAN JOURNEY TRANSFORMATION\nWITH CTE1 AS\n(SELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, UPPER(STAGE) AS STAGE, ACTION, DURATION,\nAVG(TRY_TO_NUMBER(DURATION)) OVER(PARTITION BY VISITDATE) AS AVG_DURATION,\nROW_NUMBER() OVER(PARTITION BY CUSTOMERID, PRODUCTID, VISITDATE, UPPER(STAGE), ACTION ORDER BY JOURNEYID) AS ROW_NUM\nFROM CUSTOMER_JOURNEY)\nSELECT JOURNEYID, CUSTOMERID, PRODUCTID, VISITDATE, STAGE, ACTION, COALESCE(TRY_TO_NUMBER(DURATION), AVG_DURATION) AS DURATION, ROW_NUM\nFROM CTE1 WHERE ROW_NUM = 1;\n\n-- CUSTOMER_REVIEWS EDA\nDESC TABLE CUSTOMER_REVIEWS;\nSELECT * FROM CUSTOMER_REVIEWS LIMIT 5;\nSELECT * FROM CUSTOMER_REVIEWS WHERE REVIEW_ID IS NULL OR CUSTOMER_ID IS NULL OR PRODUCT_ID IS NULL OR REVIEW_DATE IS NULL OR RATING IS NULL OR REVIEW_TEXT IS NULL;\nSELECT MIN(REVIEW_DATE), MAX(REVIEW_DATE) FROM CUSTOMER_REVIEWS;\nSELECT MIN(RATING), MAX(RATING) FROM CUSTOMER_REVIEWS;\nSELECT * FROM (SELECT *, ROW_NUMBER() OVER(PARTITION BY REVIEW_ID, CUSTOMER_ID, PRODUCT_ID, REVIEW_DATE, RATING, REVIEW_TEXT ORDER BY REVIEW_ID) AS ROW_NUM FROM CUSTOMER_REVIEWS) WHERE ROW_NUM = 1;\n\n-- CUSTOMER_ENGAGEMENT EDA / CLEANING\nDESC TABLE CUSTOMERS_ENGAGEMENT;\nSELECT * FROM CUSTOMERS_ENGAGEMENT LIMIT 5;\nSELECT COUNT(*) FROM CUSTOMERS_ENGAGEMENT;\nSELECT ENGAGEMENT_ID, COUNT(*) FROM CUSTOMERS_ENGAGEMENT GROUP BY ENGAGEMENT_ID HAVING COUNT(*) > 1;\nSELECT * FROM CUSTOMERS_ENGAGEMENT WHERE ENGAGEMENT_ID IS NULL OR CONTENT_TYPE IS NULL OR LIKES IS NULL OR ENGAGEMENT_DATE IS NULL OR PRODUCT_ID IS NULL OR VIEWS_CLICKS IS NULL;\nSELECT MIN(ENGAGEMENT_DATE), MAX(ENGAGEMENT_DATE) FROM CUSTOMERS_ENGAGEMENT;\nSELECT CONTENT_TYPE, COUNT(CONTENT_TYPE) FROM CUSTOMERS_ENGAGEMENT GROUP BY CONTENT_TYPE ORDER BY COUNT(CONTENT_TYPE);\n\n-- Clean and normalize engagement data\nSELECT ENGAGEMENT_ID, CONTENT_ID, CAMPAIGN_ID, PRODUCT_ID,\n       REPLACE(UPPER(CONTENT_TYPE),'SOCIALMEDIA', 'SOCIAL MEDIA') AS CONTENT_TYPE,\n       TRY_TO_NUMBER(LEFT(VIEWS_CLICKS, CHARINDEX('-', VIEWS_CLICKS) -1 )) AS VIEWS,\n       TRY_TO_NUMBER(RIGHT(VIEWS_CLICKS, LEN(VIEWS_CLICKS) - CHARINDEX('-', VIEWS_CLICKS))) AS CLICKS,\n       LIKES, ENGAGEMENT_DATE\nFROM CUSTOMERS_ENGAGEMENT\nWHERE UPPER(TRIM(CONTENT_TYPE)) <> 'NEWSLETTER';\n\n-- GEOGRAPHY EDA\nDESC TABLE GEOGRAPHY;\nSELECT * FROM GEOGRAPHY;\n\n-- PRODUCTS EDA / TRANSFORMATION\nDESC TABLE PRODUCTS;\nSELECT * FROM PRODUCTS;\nSELECT *,\n     CASE\n      WHEN price < 50 THEN 'Low'\n      WHEN price BETWEEN 50 AND 200 THEN 'Medium'\n      WHEN price > 200 THEN 'High'\n      END AS price_category\nFROM products;\n